  'quote.10.author': 'Sophia Bush',
  'quote.11.text': 'Lối thoát duy nhất là đi xuyên qua nó.',
  'quote.11.author': 'Robert Frost',
  'quote.12.text': 'Dù bạn ở đâu, hãy có mặt trọn vẹn ở đó.',
  'quote.12.author': 'Eckhart Tolle',
  'quote.13.text': 'Hành trình ngàn dặm bắt đầu từ một bước chân.',
